pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0xABCD);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.Put{value: 1 ether}(0); // unlockTime set to block.timestamp (0)
        vm.warp(block.timestamp + 7 days);

        // Collect 1 ether once
        vm.prank(alice);
        c.Collect(1 ether);

        // After this single Collect, the Log's History array length should be 2 (Put + 1 Collect)
        // Reference: only one Collect log entry because reentrancy guard prevents ghost calls
        // Buggy: the nonReentrant_ modifier is ineffective, but with no reentrancy here the length still 2.
        // Wait — the difference is deeper: after a single Collect, the buggy version's nonReentrant_ modifier
        // sets locked_ = false even though it never locked, but that doesn't affect public state directly.
        // Let's use a different observable: the buggy contract allows a second call that the reference would
        // revert due to balance insufficient? No, both allow second call with 0 balance but it reverts.
        // Actually the key difference is: the buggy modifier does NOT set locked_ = true before executing,
        // so a reentrant call from within Collect itself (e.g., the msg.sender.call) could re-enter Collect
        // and succeed, doubling the deduction. The reference blocks that. So we need a reentrant call.

        // Rethink: Use a malicious contract that reenters Collect on receive. But the test must be
        // fully concrete and simple. Let's instead exploit the difference via Log's History length:
        // The buggy modifier still set locked_ = false after, but the reference sets locked_ = true
        // before and false after. This does not affect History length for a single call.
        // 
        // The only observable difference for a simple single call without reentrancy is that
        // the reference has locked_ = false after, buggy also has locked_ = false after (because both end
        // with false). So no divergence.
        //
        // Therefore we must use a reentrant contract. Let's do that:
        // Malicious contract that on receive calls Collect(1 ether) again.
        Reentrant attacker = new Reentrant(c, alice);
        vm.deal(address(attacker), 10 ether);
        vm.prank(address(attacker));
        c.Put{value: 2 ether}(block.timestamp);
        vm.warp(block.timestamp + 7 days);

        // Prepare attacker's balance: it has 2 ether, unlockTime now met.
        // Now attacker calls Collect(1 ether) from its own account?
        // Actually we need attacker to call Collect on behalf of itself?
        // But Put was from attacker, so Acc[attacker] has balance 2 ether.
        // Then attacker calls Collect(1 ether): the call succeeds, balance becomes 1 ether,
        // and the transfer triggers receive() which reenters Collect(1 ether).
        // Reference: reentrancy blocked, second Collect reverts, balance stays 1 ether.
        // Buggy: second Collect succeeds, balance becomes 0.

        vm.prank(address(attacker));
        c.Collect(1 ether);

        // Now check c.Acc(address(attacker)).balance
        (uint256 unlockTime, uint256 balance) = c.Acc(address(attacker));
        // Reference: balance = 1 ether (second call reverted)
        // Buggy: balance = 0 ether (second call succeeded)
        assertTrue(balance == 1 ether, "Balance should be 1 ether in reference");
    }
}

contract Reentrant {
    C public target;
    address public owner;
    constructor(C _target, address _owner) {
        target = _target;
        owner = _owner;
    }
    receive() external payable {
        if (address(target).balance >= 1 ether) {
            target.Collect(1 ether);
        }
    }
}

